#!/usr/bin/env python
# ── GENERATED by matsci-knowledge-base build/build_plugin.py — DO NOT EDIT (真源见 plugin.yaml) ──
# -*- coding: utf-8 -*-
"""快照每个批次的完成度，供会话中断后恢复用。

批次清单（QC 工作目录下 queue.json，见 kb_lib.qc_work_dir）里的页面名可能属于
wiki/sources / concepts / topics / entities / outputs 任一目录，本脚本自动定位。

用法:
    python tools/qc_batch_progress.py              # 快照并打印
    python tools/qc_batch_progress.py --selftest   # 校验器自检
"""
import sys, os, re, json, glob, argparse


ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import read_text, qc_input, qc_work_dir  # noqa: E402
from kb_lib import console_encoding
console_encoding()

DIRS = ["wiki/sources", "wiki/concepts", "wiki/topics",
        "wiki/entities", "wiki/outputs"]


def find(name):
    for d in DIRS:
        p = os.path.join(d, name + ".md")
        if os.path.exists(p):
            return p
    return None


def compute():
    """返回 (snap, 全库真实进度 dict)。"""
    qp = qc_input("queue.json")
    if not os.path.exists(qp):
        raise SystemExit(f"queue.json 不存在（{qp}）：请先建立批次队列，"
                         "见 skills/kb-qc-loop/references/protocol.md")
    Q = json.load(open(qp, encoding="utf-8"))
    snap = {}
    for b, pages in Q.items():
        graded, missing_file = 0, []
        for p in pages:
            fp = find(p)
            if not fp:
                missing_file.append(p)
                continue
            if re.search(r"^qc_status:", read_text(fp), re.M):
                graded += 1
        snap[b] = {"total": len(pages), "graded": graded,
                   "done": graded == len(pages), "not_found": missing_file}

    # ⚠️ 直接测量全库 —— 队列内完成率会误导（队列是静态的，与实际差集随执行漂移）
    meta = {"index", "log", "log_ops", "log_insights"}
    left, total = 0, 0
    for f in glob.glob("wiki/**/*.md", recursive=True):
        q = f.replace(os.sep, "/")
        if "/.index/" in q or ".claude-rename" in q:
            continue
        if os.path.basename(f)[:-3] in meta:
            continue
        total += 1
        if not re.search(r"^qc_status:", read_text(f), re.M):
            left += 1
    return snap, {"graded": total - left, "total": total, "left": left}


def selftest():
    """校验器自检：合成夹具（正例 + 反例），不断言任何具体库的当前状态。"""
    import tempfile
    ok = True
    saved_cwd = os.getcwd()
    saved_env = os.environ.get("MATSCI_QC_DIR")
    with tempfile.TemporaryDirectory() as td:
        os.makedirs(os.path.join(td, "wiki", "sources"))
        with open(os.path.join(td, "wiki", "sources", "夹具页.md"), "w",
                  encoding="utf-8") as f:
            f.write("---\ntype: source\nqc_status: fixed\n---\n正文\n")
        qdir = os.path.join(td, ".qc")
        os.makedirs(qdir)
        with open(os.path.join(qdir, "queue.json"), "w", encoding="utf-8") as f:
            json.dump({"B1": ["夹具页"]}, f, ensure_ascii=False)
        os.environ["MATSCI_QC_DIR"] = qdir
        os.chdir(td)
        try:
            snap, real = compute()
            good = (snap.get("B1", {}).get("graded") == 1
                    and snap["B1"]["done"] is True)
            print(f"  [{'ok' if good else 'FAIL'}] 合成队列：find()+qc_status 扫描 -> {snap}")
            ok = ok and good
            good = 0 <= real["left"] <= real["total"] and real["total"] >= 1
            print(f"  [{'ok' if good else 'FAIL'}] 全库进度自洽 -> "
                  f"{real['graded']}/{real['total']}")
            ok = ok and good
            nf = find("绝不存在的页面-xyz")
            print(f"  [{'ok' if nf is None else 'FAIL'}] 反例 find(不存在) -> None")
            ok = ok and nf is None
        finally:
            os.chdir(saved_cwd)
            if saved_env is None:
                os.environ.pop("MATSCI_QC_DIR", None)
            else:
                os.environ["MATSCI_QC_DIR"] = saved_env
    # 正例：写盘目标必须在「库根 .qc」，**不得**落到 _archive
    wd = qc_work_dir(create=True)
    safe = "_archive" not in wd.replace("/", "\\")
    print(f"  [{'ok' if safe else 'FAIL'}] 写盘目标在库根、未落归档 -> {wd}")
    ok = ok and safe
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()
    if a.selftest:
        return selftest()

    snap, real = compute()
    # 写盘一律写「库根 .qc」（create=True 会建目录并阻断误写归档）
    out = os.path.join(qc_work_dir(create=True), "batch_progress.json")
    json.dump(snap, open(out, "w", encoding="utf-8"),
              ensure_ascii=False, indent=1)

    for b, v in snap.items():
        mark = "✅" if v["done"] else ("🔄" if v["graded"] else "⏳")
        extra = "  ⚠️未找到 %d 页" % len(v["not_found"]) if v["not_found"] else ""
        print("  %-5s %s  %d/%d%s" % (b, mark, v["graded"], v["total"], extra))
    ndone = sum(1 for v in snap.values() if v["done"])
    print("\n批次完成 %d/%d ｜ 队列内页面 %d/%d"
          % (ndone, len(snap),
             sum(v["graded"] for v in snap.values()),
             sum(v["total"] for v in snap.values())))
    print("全库真实进度：已评分 %d/%d ｜ 未评分 **%d 页**"
          % (real["graded"], real["total"], real["left"]))
    print("（注：队列是静态快照，与全库差集随执行漂移）")
    print("快照 -> %s" % out)
    return 0


if __name__ == "__main__":
    sys.exit(main())
